import { promises as fs } from 'node:fs';
import { join } from 'node:path';
import { ensureStorage } from './core/storage.js';
import { validateSkill } from './core/validator.js';
import { createSkill } from './core/creator.js';
import { installSkill } from './core/installer.js';
import { listInstalledSkills, searchSkills, getInstalledSkill, removeSkill, getRegistryStats, rebuildRegistry, exportSkill, } from './core/registry.js';
import { runSkill } from './core/runner.js';
import { loadConfig, getConfigValue, setConfigValue } from './core/config.js';
import { SkillLaneError } from './core/errors.js';
// ── ANSI Colors ──────────────────────────────────────────────────────────────
const c = {
    reset: '\x1b[0m',
    bold: '\x1b[1m',
    dim: '\x1b[2m',
    red: '\x1b[31m',
    green: '\x1b[32m',
    yellow: '\x1b[33m',
    blue: '\x1b[34m',
    magenta: '\x1b[35m',
    cyan: '\x1b[36m',
};
function bold(text) { return `${c.bold}${text}${c.reset}`; }
function green(text) { return `${c.green}${text}${c.reset}`; }
function red(text) { return `${c.red}${text}${c.reset}`; }
function yellow(text) { return `${c.yellow}${text}${c.reset}`; }
function cyan(text) { return `${c.cyan}${text}${c.reset}`; }
function dim(text) { return `${c.dim}${text}${c.reset}`; }
function success(text) { return `${c.bold}${c.green}✓${c.reset} ${text}`; }
function fail(text) { return `${c.bold}${c.red}✗${c.reset} ${text}`; }
function warn(text) { return `${c.bold}${c.yellow}⚠${c.reset} ${text}`; }
function info(text) { return `${c.bold}${c.cyan}ℹ${c.reset} ${text}`; }
// ── Version ──────────────────────────────────────────────────────────────────
let _version;
async function getVersion() {
    if (_version)
        return _version;
    try {
        const pkg = JSON.parse(await fs.readFile(join(new URL('../', import.meta.url).pathname, 'package.json'), 'utf-8'));
        _version = pkg.version || '0.0.0';
    }
    catch {
        _version = '0.1.0';
    }
    return _version;
}
function parseArgs(argv) {
    const args = argv.slice(2);
    const result = {
        command: null,
        subcommand: null,
        positional: [],
        flags: {},
    };
    let i = 0;
    const positional = [];
    while (i < args.length) {
        const arg = args[i];
        if (arg === '--') {
            i++;
            while (i < args.length) {
                positional.push(args[i]);
                i++;
            }
            break;
        }
        if (arg.startsWith('--')) {
            const eqIdx = arg.indexOf('=');
            if (eqIdx !== -1) {
                const key = arg.slice(2, eqIdx);
                const val = arg.slice(eqIdx + 1);
                result.flags[key] = val;
            }
            else {
                const key = arg.slice(2);
                const next = args[i + 1];
                if (next && !next.startsWith('-')) {
                    result.flags[key] = next;
                    i++;
                }
                else {
                    result.flags[key] = true;
                }
            }
        }
        else if (arg.startsWith('-') && arg.length === 2) {
            const key = arg.slice(1);
            const next = args[i + 1];
            if (next && !next.startsWith('-')) {
                result.flags[key] = next;
                i++;
            }
            else {
                result.flags[key] = true;
            }
        }
        else if (arg.startsWith('-') && arg.length > 2 && arg[1] !== '-') {
            for (let j = 1; j < arg.length; j++) {
                result.flags[arg[j]] = true;
            }
        }
        else {
            positional.push(arg);
        }
        i++;
    }
    if (positional.length > 0) {
        result.command = positional[0];
        result.positional = positional.slice(1);
    }
    if (result.command && ['config', 'registry'].includes(result.command) && positional.length > 1) {
        result.subcommand = positional[1];
        result.positional = positional.slice(2);
    }
    return result;
}
// ── Help Text ────────────────────────────────────────────────────────────────
async function showHelp() {
    const version = await getVersion();
    console.log(`
${bold(`${c.cyan}SkillLane${c.reset} ${dim(`v${version}`)}`)}
${dim('Open-source skill runtime for AI agents')}

${bold('USAGE')}
  ${cyan('skilllane')} <command> [options]

${bold('COMMANDS')}
  ${green('init')}                        Initialize ~/.skilllane directory
  ${green('create')} <name>               Create a new skill
  ${green('validate')} <path>             Validate a skill folder
  ${green('install')} <source>            Install a skill from a path
  ${green('list')}                        List installed skills
  ${green('search')} <query>              Search installed skills
  ${green('show')} <name>                 Show skill details
  ${green('run')} <name>                  Run a skill
  ${green('remove')} <name>               Remove an installed skill
  ${green('export')} <name>               Export a skill to a directory
  ${green('serve')}                       Start the HTTP API server
  ${green('mcp')}                         Start the MCP server
  ${green('doctor')}                      Check system health
  ${green('demo')}                        Run deterministic demo
  ${green('registry')} <subcommand>       Registry management
  ${green('config')} <subcommand>         Configuration management

${bold('REGISTRY SUBCOMMANDS')}
  ${cyan('registry path')}               Show registry file path
  ${cyan('registry rebuild')}            Rebuild registry from installed skills
  ${cyan('registry stats')}              Show registry statistics

${bold('CONFIG SUBCOMMANDS')}
  ${cyan('config get')} <key>            Get a config value
  ${cyan('config set')} <key> <value>    Set a config value
  ${cyan('config list')}                 List all config values

${bold('OPTIONS')}
  ${yellow('-h, --help')}                 Show this help message
  ${yellow('-v, --version')}              Show version number
  ${yellow('--json')}                     Output as JSON
  ${yellow('--strict')}                   Strict validation mode

${bold('CREATE OPTIONS')}
  ${yellow('--title')} <title>            Skill display title
  ${yellow('--description')} <desc>       Skill description
  ${yellow('--category')} <cat>           Category: engineering, marketing, design, writing, devops, research, general
  ${yellow('--tags')} <t1,t2,...>         Comma-separated tags
  ${yellow('--targets')} <t1,t2,...>      Comma-separated targets: codex, opencode, codra, tera, mcp, clipboard, stdout
  ${yellow('--template')} <name>          Template to use (basic, debugging, writing, product-launch)
  ${yellow('--out')} <dir>                Output directory

${bold('INSTALL OPTIONS')}
  ${yellow('--builtin')}                  Install from built-in skills directory
  ${yellow('--name')} <name>              Custom name for the installed skill
  ${yellow('--force')}                    Overwrite existing installation

${bold('LIST OPTIONS')}
  ${yellow('--tag')} <tag>                Filter by tag
  ${yellow('--category')} <cat>           Filter by category

${bold('RUN OPTIONS')}
  ${yellow('--task')} <task>              Task description for the skill
  ${yellow('--context')} <text>           Context string
  ${yellow('--target')} <target>          Target runtime
  ${yellow('--out')} <path>               Output file path

${bold('SERVE OPTIONS')}
  ${yellow('--port')} <port>              Port number (default: 3000)

${bold('EXAMPLES')}
  ${dim('$ skilllane init')}
  ${dim('$ skilllane create my-skill --title "My Skill" --category engineering')}
  ${dim('$ skilllane validate ./my-skill')}
  ${dim('$ skilllane install ./my-skill')}
  ${dim('$ skilllane install --builtin systematic-debugging')}
  ${dim('$ skilllane list --category engineering')}
  ${dim('$ skilllane run systematic-debugging --task "Fix this bug"')}
  ${dim('$ skilllane demo')}
`);
}
// ── Commands ─────────────────────────────────────────────────────────────────
async function cmdInit() {
    await ensureStorage();
    console.log(success(`Initialized SkillLane at ${join(process.env.HOME || '~', '.skilllane')}`));
}
async function cmdCreate(positional, flags) {
    const name = positional[0];
    if (!name) {
        console.error(fail('Please provide a skill name: skilllane create <name>'));
        process.exit(1);
    }
    const title = typeof flags.title === 'string' ? flags.title : name.split('-').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
    const description = typeof flags.description === 'string' ? flags.description : `A skill for ${title.toLowerCase()} tasks`;
    const input = {
        name,
        title,
        description,
        category: (typeof flags.category === 'string' ? flags.category : 'general'),
        targets: typeof flags.targets === 'string' ? flags.targets.split(',').map(t => t.trim()) : undefined,
        tags: typeof flags.tags === 'string' ? flags.tags.split(',').map(t => t.trim()) : undefined,
        template: typeof flags.template === 'string' ? flags.template : undefined,
        outDir: typeof flags.out === 'string' ? flags.out : process.cwd(),
    };
    const definition = await createSkill(input);
    console.log(success(`Created skill ${bold(definition.metadata.name)} at ${cyan(definition.path)}`));
    console.log(dim(`  Files: metadata.json, SKILL.md, tools.json, examples.md, eval.md`));
}
async function cmdValidate(positional, flags) {
    const path = positional[0];
    if (!path) {
        console.error(fail('Please provide a path: skilllane validate <path>'));
        process.exit(1);
    }
    const result = await validateSkill(path, { strict: flags.strict === true });
    if (flags.json === true) {
        console.log(JSON.stringify(result, null, 2));
        return;
    }
    console.log('');
    console.log(bold(`Validating: ${cyan(path)}`));
    console.log(dim(`  Files checked: ${result.checkedFiles.length}`));
    console.log('');
    if (result.metadata) {
        console.log(info(`Skill: ${bold(result.metadata.title)} (${result.metadata.name} v${result.metadata.version})`));
        console.log(dim(`  Category: ${result.metadata.category} | Tags: ${result.metadata.tags.join(', ')}`));
        console.log('');
    }
    const scoreColor = result.score >= 80 ? green : result.score >= 50 ? yellow : red;
    console.log(`  Score: ${scoreColor(String(result.score))}/100`);
    console.log('');
    if (result.errors.length > 0) {
        console.log(red(`  Errors (${result.errors.length}):`));
        for (const err of result.errors) {
            console.log(`    ${c.red}•${c.reset} ${err}`);
        }
        console.log('');
    }
    if (result.warnings.length > 0) {
        console.log(yellow(`  Warnings (${result.warnings.length}):`));
        for (const w of result.warnings) {
            console.log(`    ${c.yellow}•${c.reset} ${w}`);
        }
        console.log('');
    }
    if (result.valid) {
        console.log(success('Skill is valid!'));
    }
    else {
        console.log(fail('Skill validation failed.'));
        process.exit(1);
    }
}
async function cmdInstall(positional, flags) {
    const source = positional[0];
    if (!source) {
        console.error(fail('Please provide a source: skilllane install <source>'));
        process.exit(1);
    }
    const entry = await installSkill(source, {
        builtin: flags.builtin === true,
        name: typeof flags.name === 'string' ? flags.name : undefined,
        force: flags.force === true,
    });
    console.log(success(`Installed ${bold(entry.title)} (${cyan(entry.name)} v${entry.version})`));
    console.log(dim(`  Path: ${entry.path}`));
}
async function cmdList(flags) {
    const skills = await listInstalledSkills({
        tag: typeof flags.tag === 'string' ? flags.tag : undefined,
        category: typeof flags.category === 'string' ? flags.category : undefined,
    });
    if (flags.json === true) {
        console.log(JSON.stringify(skills, null, 2));
        return;
    }
    if (skills.length === 0) {
        console.log(info('No skills installed. Use `skilllane install` to add skills.'));
        return;
    }
    console.log('');
    console.log(bold(`Installed Skills (${skills.length})`));
    console.log(dim('─'.repeat(60)));
    for (const skill of skills) {
        console.log(`  ${green('●')} ${bold(skill.title)} ${dim(`(${skill.name} v${skill.version})`)}`);
        console.log(dim(`    ${skill.description}`));
        console.log(dim(`    Category: ${skill.category} | Tags: ${skill.tags.join(', ')}`));
        console.log(dim(`    Targets: ${skill.targets.join(', ')} | Installed: ${skill.installedAt}`));
        console.log('');
    }
}
async function cmdSearch(positional) {
    const query = positional[0];
    if (!query) {
        console.error(fail('Please provide a query: skilllane search <query>'));
        process.exit(1);
    }
    const results = await searchSkills(query);
    if (results.length === 0) {
        console.log(info(`No skills found matching "${query}".`));
        return;
    }
    console.log('');
    console.log(bold(`Search Results for "${query}" (${results.length})`));
    console.log(dim('─'.repeat(60)));
    for (const skill of results) {
        console.log(`  ${green('●')} ${bold(skill.title)} ${dim(`(${skill.name} v${skill.version})`)}`);
        console.log(dim(`    ${skill.description}`));
        console.log(dim(`    Category: ${skill.category} | Tags: ${skill.tags.join(', ')}`));
        console.log('');
    }
}
async function cmdShow(positional) {
    const name = positional[0];
    if (!name) {
        console.error(fail('Please provide a skill name: skilllane show <name>'));
        process.exit(1);
    }
    const entry = await getInstalledSkill(name);
    console.log('');
    console.log(bold(`${c.cyan}${entry.title}${c.reset}`));
    console.log(dim('─'.repeat(60)));
    console.log(`  ${dim('Name:')}        ${entry.name}`);
    console.log(`  ${dim('Version:')}     ${entry.version}`);
    console.log(`  ${dim('Category:')}    ${entry.category}`);
    console.log(`  ${dim('Tags:')}        ${entry.tags.join(', ')}`);
    console.log(`  ${dim('Targets:')}     ${entry.targets.join(', ')}`);
    console.log(`  ${dim('Installed:')}   ${entry.installedAt}`);
    console.log(`  ${dim('Path:')}        ${entry.path}`);
    console.log('');
    if (entry.description) {
        console.log(bold('  Description'));
        console.log(dim(`  ${entry.description}`));
        console.log('');
    }
}
async function cmdRun(positional, flags) {
    const name = positional[0];
    if (!name) {
        console.error(fail('Please provide a skill name: skilllane run <name>'));
        process.exit(1);
    }
    const task = typeof flags.task === 'string' ? flags.task : positional[1] || 'General task';
    console.log(info(`Running skill ${bold(name)}...`));
    console.log('');
    const result = await runSkill({
        skillName: name,
        skillPath: '',
        task,
        context: typeof flags.context === 'string' ? flags.context : '',
        target: (typeof flags.target === 'string' ? flags.target : 'opencode'),
        variables: {},
        mode: 'prompt',
    });
    console.log(bold(`${c.cyan}Prompt Output${c.reset}`));
    console.log(dim('─'.repeat(60)));
    console.log(result.prompt);
    console.log(dim('─'.repeat(60)));
    console.log('');
    if (typeof flags.out === 'string') {
        await fs.writeFile(flags.out, JSON.stringify(result, null, 2), 'utf-8');
        console.log(success(`Output saved to ${cyan(flags.out)}`));
    }
}
async function cmdRemove(positional) {
    const name = positional[0];
    if (!name) {
        console.error(fail('Please provide a skill name: skilllane remove <name>'));
        process.exit(1);
    }
    await removeSkill(name);
    console.log(success(`Removed skill ${bold(name)}.`));
}
async function cmdExport(positional, flags) {
    const name = positional[0];
    if (!name) {
        console.error(fail('Please provide a skill name: skilllane export <name>'));
        process.exit(1);
    }
    const outPath = typeof flags.out === 'string' ? flags.out : undefined;
    const resultPath = await exportSkill(name, outPath);
    console.log(success(`Exported ${bold(name)} to ${cyan(resultPath)}`));
}
async function cmdServe(flags) {
    const port = typeof flags.port === 'string' ? parseInt(flags.port, 10) : 3000;
    console.log(info(`Starting SkillLane API server on port ${bold(String(port))}...`));
    console.log(dim('Press Ctrl+C to stop.'));
    console.log('');
    try {
        const { startApiServer } = await import('./api/server.js');
        const server = await startApiServer(port);
        console.log(success(`API server running at ${cyan(`http://localhost:${port}`)}`));
        console.log(dim(`  GET  /health     - Health check`));
        console.log(dim(`  GET  /skills     - List skills`));
        console.log(dim(`  GET  /skills/:name - Get skill details`));
        console.log(dim(`  POST /validate   - Validate a skill`));
        console.log(dim(`  POST /run        - Run a skill`));
        console.log('');
    }
    catch (err) {
        if (err instanceof Error && err.message.includes('Cannot find module')) {
            console.error(fail('API server module not found. Run `npm run build` first.'));
        }
        else {
            console.error(fail(`Failed to start API server: ${err}`));
        }
        process.exit(1);
    }
}
async function cmdMcp() {
    console.log(info('Starting SkillLane MCP server...'));
    console.log(dim('Press Ctrl+C to stop.'));
    console.log('');
    try {
        const { startMcpServer } = await import('./mcp/server.js');
        await startMcpServer();
        console.log(success('MCP server connected and listening.'));
    }
    catch (err) {
        if (err instanceof Error && err.message.includes('Cannot find module')) {
            console.error(fail('MCP server module not found. Run `npm run build` first.'));
        }
        else {
            console.error(fail(`Failed to start MCP server: ${err}`));
        }
        process.exit(1);
    }
}
async function cmdDoctor() {
    console.log('');
    console.log(bold(`${c.cyan}SkillLane Doctor${c.reset}`));
    console.log(dim('─'.repeat(60)));
    const checks = [];
    // Check Node.js version
    const nodeVersion = process.version;
    const nodeMajor = parseInt(nodeVersion.slice(1), 10);
    checks.push({
        name: 'Node.js version',
        ok: nodeMajor >= 18,
        detail: `${nodeVersion} ${nodeMajor >= 18 ? '(>= 18.0.0)' : '(requires >= 18.0.0)'}`,
    });
    // Check storage directory
    try {
        const { getStorageRoot } = await import('./core/storage.js');
        const root = getStorageRoot();
        try {
            await fs.access(root);
            checks.push({ name: 'Storage directory', ok: true, detail: root });
        }
        catch {
            checks.push({ name: 'Storage directory', ok: false, detail: `${root} (not initialized, run: skilllane init)` });
        }
    }
    catch {
        checks.push({ name: 'Storage directory', ok: false, detail: 'Could not determine path' });
    }
    // Check config
    try {
        const config = await loadConfig();
        checks.push({ name: 'Config file', ok: true, detail: `defaultTarget=${config.defaultTarget}` });
    }
    catch {
        checks.push({ name: 'Config file', ok: false, detail: 'Could not load config' });
    }
    // Check registry
    try {
        const { readRegistry } = await import('./core/storage.js');
        const registry = await readRegistry();
        checks.push({ name: 'Registry', ok: true, detail: `${registry.length} skill(s) installed` });
    }
    catch {
        checks.push({ name: 'Registry', ok: false, detail: 'Could not read registry' });
    }
    // Check built-in skills
    try {
        const pkgDir = new URL('../', import.meta.url).pathname;
        const skillsDir = join(pkgDir, 'skills');
        const entries = await fs.readdir(skillsDir, { withFileTypes: true });
        const builtinCount = entries.filter(e => e.isDirectory()).length;
        checks.push({ name: 'Built-in skills', ok: builtinCount > 0, detail: `${builtinCount} skill(s) available` });
    }
    catch {
        checks.push({ name: 'Built-in skills', ok: false, detail: 'Built-in skills directory not found' });
    }
    // Print results
    console.log('');
    for (const check of checks) {
        const icon = check.ok ? green('  ✓') : red('  ✗');
        console.log(`${icon} ${bold(check.name)}: ${dim(check.detail)}`);
    }
    console.log('');
    const allOk = checks.every(c => c.ok);
    if (allOk) {
        console.log(success('All checks passed!'));
    }
    else {
        console.log(warn('Some checks failed. Run `skilllane init` to set up.'));
    }
    console.log('');
}
async function cmdDemo() {
    console.log('');
    console.log(bold(`${c.cyan}SkillLane Demo${c.reset}`));
    console.log(dim('─'.repeat(60)));
    console.log('');
    // Step 1: Ensure storage
    console.log(info('Step 1: Ensuring storage...'));
    await ensureStorage();
    console.log(success('Storage initialized.'));
    console.log('');
    // Step 2: Validate built-in skill
    console.log(info('Step 2: Validating built-in skill: systematic-debugging'));
    const pkgDir = new URL('../', import.meta.url).pathname;
    const skillPath = join(pkgDir, 'skills', 'systematic-debugging');
    const validation = await validateSkill(skillPath);
    console.log(`  Score: ${validation.score}/100`);
    console.log(`  Valid: ${validation.valid ? green('yes') : red('no')}`);
    console.log(`  Errors: ${validation.errors.length} | Warnings: ${validation.warnings.length}`);
    console.log('');
    // Step 3: Install skill
    console.log(info('Step 3: Installing skill...'));
    const entry = await installSkill('systematic-debugging', { builtin: true, force: true });
    console.log(success(`Installed ${bold(entry.title)} (${cyan(entry.name)} v${entry.version})`));
    console.log('');
    // Step 4: Run skill with fake error context
    console.log(info('Step 4: Running skill with sample TypeScript error...'));
    const sampleContext = `src/components/UserProfile.tsx(42,15): error TS2345: Argument of type '{ name: string; age: string; }' is not assignable to parameter of type 'UserProfile'.
  Types of property 'age' are incompatible.
    Type 'string' is not assignable to type 'number'.`;
    const result = await runSkill({
        skillName: 'systematic-debugging',
        skillPath: '',
        task: 'Debug a TypeScript type error in UserProfile component',
        context: sampleContext,
        target: 'opencode',
        variables: {},
        mode: 'markdown',
    });
    console.log(success('Skill executed successfully.'));
    console.log('');
    console.log(bold('Generated Prompt:'));
    console.log(dim('─'.repeat(60)));
    console.log(result.prompt);
    console.log(dim('─'.repeat(60)));
    console.log('');
    // Step 5: Save demo output
    console.log(info('Step 5: Saving demo output...'));
    const demoDir = join(new URL('../', import.meta.url).pathname, 'demo');
    await fs.mkdir(demoDir, { recursive: true });
    const demoOutput = {
        timestamp: new Date().toISOString(),
        skill: entry.name,
        version: entry.version,
        validation: {
            score: validation.score,
            valid: validation.valid,
            errors: validation.errors,
            warnings: validation.warnings,
        },
        run: {
            task: 'Debug a TypeScript type error in UserProfile component',
            outputMode: result.outputMode,
            tools: result.tools,
        },
        prompt: result.prompt,
    };
    const outputPath = join(demoDir, 'demo-output.json');
    await fs.writeFile(outputPath, JSON.stringify(demoOutput, null, 2), 'utf-8');
    console.log(success(`Demo output saved to ${cyan(outputPath)}`));
    console.log('');
    console.log(success('Demo complete! SkillLane is working correctly.'));
    console.log('');
}
async function cmdRegistry(subcommand, positional) {
    await ensureStorage();
    switch (subcommand) {
        case 'path': {
            const { getStorageRoot } = await import('./core/storage.js');
            const root = getStorageRoot();
            console.log(join(root, 'registry.json'));
            break;
        }
        case 'rebuild': {
            console.log(info('Rebuilding registry...'));
            const entries = await rebuildRegistry();
            console.log(success(`Registry rebuilt with ${bold(String(entries.length))} skill(s).`));
            break;
        }
        case 'stats': {
            const stats = await getRegistryStats();
            console.log('');
            console.log(bold('Registry Statistics'));
            console.log(dim('─'.repeat(40)));
            console.log(`  ${dim('Total skills:')}  ${bold(String(stats.totalSkills))}`);
            console.log('');
            if (Object.keys(stats.categories).length > 0) {
